  if (!existsSync(tsc)) {
    console.error("[prepare] backend is not built and typescript is missing: run `npm install` first");
    process.exit(1);
  }
  if (!run(process.execPath, [tsc, "-p", "tsconfig.json"], backendDir)) {
    console.error("[prepare] backend build failed");
    process.exit(1);
  }
}

